def load() -> pd.DataFrame:
    import openpyxl
    xl = openpyxl.load_workbook('data/biomedical/input/1-s2.0-S0092867420301070-mmc7.xlsx')
    sheets = xl.sheetnames
    dfs = {}
    for sheet in sheets:
        df = pd.read_excel('data/biomedical/input/1-s2.0-S0092867420301070-mmc7.xlsx', sheet_name=sheet)
        dfs[sheet] = df

    result_rows = []
    for sheet_name, df in dfs.items():
        cols_str = ', '.join(df.columns[:10].tolist())
        result_rows.append({
            'Sheet': sheet_name,
            'Columns_Sample': cols_str,
            'Shape': f'{df.shape[0]} rows x {df.shape[1]} cols'
        })
    return pd.DataFrame(result_rows)

