def process(load_app_z_data) -> pd.DataFrame:
    min_idx = load_app_z_data['APP_Z_score'].idxmin()
    return load_app_z_data.iloc[[min_idx]][['idx', 'APP_Z_score']]

def process(find_min_app_z, load_age_data) -> pd.DataFrame:
    result = find_min_app_z.merge(load_age_data, on='idx', how='inner')
    return result[['idx', 'APP_Z_score', 'Age']]
